const u = $json;
const cb = u.callback_query;
const msg = cb ? cb.message : u.message;
const from = cb ? cb.from : u.message.from;
return [{ json: {
  chat_id: String(msg.chat.id),
  first_name: from.first_name || '',
  text: cb ? cb.data : (u.message.text || ''),
  callback_id: cb ? cb.id : '',
  is_callback: Boolean(cb),
} }];

const j = $json;
if (!j.is_callback || !j.callback_id) return [];
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${$env.TELEGRAM_MATKOVSKA_BOT_TOKEN}/answerCallbackQuery`,
    body: { callback_query_id: j.callback_id },
    json: true,
  });
} catch (e) {
}
return [];

const t = ($json.text || '').trim();
let action = 'help', hour = null, day = null, question_id = '', correct = null,
    content_type = null, content_pref = null;

if (/^\/start\b/i.test(t)) action = 'start';
else if (/^\/settings\b/i.test(t) || t === 'su_settings_open') action = 'settings_menu';
else if (/^\/pause\b/i.test(t)) action = 'pause';
else if (/^\/resume\b/i.test(t)) action = 'resume';
else if (/^\/question\b/i.test(t)) action = 'question';
else if (/^\/dashboard\b/i.test(t)) action = 'dashboard_link';
else if (/^\/mystats\b/i.test(t)) action = 'my_stats_link';
else if (/^\/about\b/i.test(t)) action = 'about';
else if (t === 'su_schedule_open') action = 'pick_cadence';
else if (t === 'su_content_open') action = 'content_menu';
else if (t === 'su_cadence_daily') action = 'pick_hour';
else if (t === 'su_cadence_weekly') action = 'pick_day';
else {
  let m;
  if ((m = t.match(/^su_day_([0-6])$/))) { action = 'pick_hour'; day = Number(m[1]); }
  else if ((m = t.match(/^su_hour_daily_(\d+)$/))) { action = 'save_schedule'; hour = Number(m[1]); }
  else if ((m = t.match(/^su_hour_weekly_([0-6])_(\d+)$/))) {
    action = 'save_schedule'; day = Number(m[1]); hour = Number(m[2]);
  }
  else if ((m = t.match(/^su_content_(vocab|grammar|both)$/))) {
    action = 'save_content'; content_pref = m[1];
  }
  else if ((m = t.match(/^qz_(correct|wrong)_(vocab|grammar)_(\d+)$/))) {
    action = 'answer'; correct = m[1] === 'correct'; content_type = m[2]; question_id = m[3];
  }
}
return [{ json: { ...$json, action, hour, day, question_id, correct, content_type, content_pref } }];

const day = $('Route').item.json.day;
const chat_id = $('Route').item.json.chat_id;
const mk = (h, emoji) => ({ text: `${emoji} ${h}:00`,
  callback_data: day != null ? `su_hour_weekly_${day}_${h}` : `su_hour_daily_${h}` });
const buttons = [[mk(9, '☀️'), mk(14, '🌤️'), mk(19, '🌙')]];
return [{ json: { chat_id: chat_id, body: JSON.stringify({
  chat_id: chat_id, text: 'Pick a time (Kyiv time):',
  reply_markup: { inline_keyboard: buttons } }) } }];

const j = $('Route').item.json;
const cadence = j.day != null ? 'weekly' : 'daily';
const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const when = cadence === 'weekly'
  ? `every ${dayNames[j.day]} at ${j.hour}:00`
  : `every day at ${j.hour}:00`;
return [{ json: {
  chat_id: j.chat_id,
  body: JSON.stringify({ chat_id: Number(j.chat_id), cadence,
    send_hour: j.hour, send_day: j.day }),
  reply_text: `Updated! You'll get a question ${when} (Kyiv time).`,
} }];

const j = $('Route').item.json;
const labels = { vocab: 'vocabulary only', grammar: 'grammar only',
  both: 'a mix of vocabulary and grammar' };
return [{ json: {
  chat_id: j.chat_id,
  body: JSON.stringify({ chat_id: Number(j.chat_id), content_pref: j.content_pref }),
  reply_text: `Updated! You'll now get ${labels[j.content_pref]}.`,
} }];

const j = $('Route').item.json;
const row = $input.first().json;
const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
let text;
if (row && row.cadence) {
  const when = row.cadence === 'weekly'
    ? `every ${dayNames[row.send_day]} at ${row.send_hour}:00`
    : `every day at ${row.send_hour}:00`;
  text = `Welcome back! Your current schedule: ${when} (Kyiv time).\n⚙️ Change frequency anytime with /settings.`;
} else {
  text = "You're subscribed! One question a day at 9:00 (Kyiv time).\n⚙️ Change frequency anytime with /settings.";
}
return [{ json: { chat_id: j.chat_id, reply_text: text } }];

const j = $('Route').item.json;
const row = $input.first().json;
const CORRECT_PHRASES = ['✅ Correct!', '✅ Nailed it!', '✅ Yes, exactly!', '✅ Nice one!', '✅ Spot on!'];
const WRONG_OPENERS = ['❌ Not quite', '❌ Almost', '❌ Close, but not quite', '❌ Nope'];
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
let text;
if (j.correct) {
  text = pick(CORRECT_PHRASES);
} else {
  const correctText = row && row.options && row.options[row.correct_option_index];
  text = correctText ? `${pick(WRONG_OPENERS)} — it's "${correctText}".` : pick(WRONG_OPENERS) + '.';
}
if (row && row.explanation) text += `\n\n💡 ${row.explanation}`;
return [{ json: { chat_id: j.chat_id, text } }];

const j = $('Route').item.json;
const CORRECT_PHRASES = ['✅ Correct!', '✅ Nailed it!', '✅ Yes, exactly!', '✅ Nice one!', '✅ Spot on!'];
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
return [{ json: { chat_id: j.chat_id, text: pick(CORRECT_PHRASES) } }];

const j = $('Route').item.json;
const row = $input.first().json;
const WRONG_OPENERS = ['❌ Not quite', '❌ Almost', '❌ Close, but not quite', '❌ Nope'];
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
const translation = row && row.translation;
const text = translation ? `${pick(WRONG_OPENERS)} — it's "${translation}".` : pick(WRONG_OPENERS) + '.';
return [{ json: { chat_id: j.chat_id, text } }];

const text0 = $json.text;
const chatId = $json.chat_id;
const recent = $('Get Recent Answers').all().map(i => i.json);
let streak = 0;
for (const row of recent) { if (row.correct) streak++; else break; }
let text = text0;
if (streak >= 2) text += `\n🔥 ${streak} in a row!`;
return [{ json: { chat_id: chatId, reply_text: text } }];

const j = $('Route').item.json;
const session = $json;
let askedVocabIds = session.asked_vocab_ids || [];
let askedGrammarIds = session.asked_grammar_ids || [];
if (j.content_type === 'grammar') askedGrammarIds = [...askedGrammarIds, Number(j.question_id)];
else askedVocabIds = [...askedVocabIds, Number(j.question_id)];
const questionIndex = session.question_index + 1;
const correctCount = session.correct_count + (j.correct ? 1 : 0);
return [{ json: { chat_id: j.chat_id, questionIndex, correctCount, askedVocabIds, askedGrammarIds } }];

const j = $('Compute New Session State').item.json;
const recent = $input.all().map(i => i.json);
let streak = 0;
for (const row of recent) { if (row.correct) streak++; else break; }
let text = `🏁 Round complete: ${j.correctCount}/3`;
if (streak >= 2) text += `\n🔥 ${streak} in a row!`;
return [{ json: { chat_id: j.chat_id, text } }];

const chatId = $('Route').item.json.chat_id;
const ADMIN_CHAT_IDS = [863273840, 5507304303]; // Oleksandr, Matkovska

if (!ADMIN_CHAT_IDS.includes(Number(chatId))) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${$env.TELEGRAM_MATKOVSKA_BOT_TOKEN}/sendMessage`,
    body: { chat_id: chatId, text: "That command isn't available for your account." },
    json: true,
  });
  return [];
}

const url = `https://n8n.englishpusher.in.ua/webhook/matkovska-quiz-dashboard?token=${$env.DASHBOARD_ADMIN_TOKEN}`;
await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${$env.TELEGRAM_MATKOVSKA_BOT_TOKEN}/sendMessage`,
  body: { chat_id: chatId, text: `\u{1F4CA} <a href="${url}">Open your Dashboard</a>`, parse_mode: 'HTML' },
  json: true,
});
return [];

const chatId = $('Route').item.json.chat_id;

const sub = await this.helpers.httpRequest({
  method: 'GET',
  url: `${$env.SUPABASE_URL}/rest/v1/subscribers`,
  qs: { chat_id: `eq.${chatId}`, select: 'dashboard_token' },
  headers: { apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
             Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
             'Accept-Profile': 'matkovska_quiz_bot' },
  json: true,
});

if (!sub || !sub[0]) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${$env.TELEGRAM_MATKOVSKA_BOT_TOKEN}/sendMessage`,
    body: { chat_id: chatId, text: 'Use /start first to subscribe, then /mystats will show your personal link.' },
    json: true,
  });
  return [];
}

const url = `https://n8n.englishpusher.in.ua/webhook/matkovska-quiz-dashboard?token=${sub[0].dashboard_token}`;
await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${$env.TELEGRAM_MATKOVSKA_BOT_TOKEN}/sendMessage`,
  body: { chat_id: chatId, text: `\u{1F4CA} <a href="${url}">Your personal stats</a>`, parse_mode: 'HTML' },
  json: true,
});
return [];

const SECRET = $env.MATKOVSKA_NEW_SUBSCRIBER_WEBHOOK_SECRET;
const h = $json.headers || {};
const secret = h['x-webhook-secret'] || h['X-Webhook-Secret'] || '';
const b = $json.body || {};
if (secret !== SECRET || b.type !== 'INSERT' || b.table !== 'subscribers') return [];
const r = b.record || {};
return [{ json: { chat_id: r.chat_id, first_name: r.first_name || '' } }];
